'use strict';
// Research only: volatility-regime reversal, session reversal, M5/H1 dislocation.
// 75% DEV / 25% untouched HOLD; next M5 open; one open/model; SL first if same bar.
const fs=require('fs');const R=JSON.parse(fs.readFileSync('data/xauusd-m5-dukascopy.json','utf8'));
const M=R.map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t),N=M.length,C=Math.floor(N*.75);
function ema(p){let E=Array(N).fill(NaN),k=2/(p+1),e=M[0].c;for(let i=0;i<N;i++){e=M[i].c*k+e*(1-k);E[i]=e}return E}function atr(p=14){let A=Array(N).fill(NaN);for(let i=p;i<N;i++){let s=0;for(let j=i-p+1;j<=i;j++)s+=Math.max(M[j].h-M[j].l,Math.abs(M[j].h-M[j-1].c),Math.abs(M[j].l-M[j-1].c));A[i]=s/p}return A}const A=atr(),E20=ema(20),E50=ema(50);const hour=i=>new Date(M[i].t).getUTCHours();
function avga(i,n){let s=0,c=0;for(let j=i-n;j<i;j++)if(Number.isFinite(A[j])){s+=A[j];c++}return c?n? s/c:NaN:NaN}function run(sig,cfg,lo,hi){let T=[],o=null;for(let i=Math.max(100,lo);i<Math.min(N-1,hi);i++){if(o){let b=M[i],px=null;if(o.s==='BUY'){if(b.l<=o.sl)px=o.sl;else if(b.h>=o.tp)px=o.tp}else{if(b.h>=o.sl)px=o.sl;else if(b.l<=o.tp)px=o.tp}if(px==null&&i-o.ei+1>=cfg.hold)px=b.c;if(px!=null){T.push({...o,r:o.s==='BUY'?(px-o.en)/(o.en-o.sl):(o.en-px)/(o.sl-o.en)});o=null}continue}let s=sig(i);if(!s||!Number.isFinite(A[i]))continue;let en=M[i+1].o,r=cfg.sl*A[i];o={s,en,sl:s==='BUY'?en-r:en+r,tp:s==='BUY'?en+cfg.rr*r:en-cfg.rr*r,ei:i+1}}return T}function st(T){let w=0,g=0,l=0,e=0,p=0,d=0,ls=0,ml=0;for(let x of T){e+=x.r;if(x.r>0){w++;g+=x.r;ls=0}else{l+=-x.r;ls++;ml=Math.max(ml,ls)}p=Math.max(p,e);d=Math.max(d,p-e)}return{n:T.length,wr:T.length?100*w/T.length:0,pf:l?g/l:g?Infinity:0,net:e,dd:d,ls:ml}}
let X=[];function add(f,cfg,fn){let d=st(run(fn,cfg,0,C));if(d.n<30)return;X.push({f,cfg,fn,d,score:d.net+Math.min(d.pf,3)*6-d.dd*.7})}
// REGREV: abnormal ATR regime + stretched distance from EMA20 followed by reversal candle.
for(let ar of [1.25,1.5,1.8])for(let dist of [1,1.5,2])for(let cp of [.65,.8])for(let rr of [1,1.25,1.5]){let cfg={ar,dist,cp,rr,sl:1,hold:10};add('REGREV',cfg,i=>{let aa=avga(i,50);if(!(A[i]/aa>=ar))return;let b=M[i],rg=b.h-b.l;if(!(rg>0))return;if((E20[i]-b.c)/A[i]>=dist&&b.c>b.o&&(b.c-b.l)/rg>=cp)return'BUY';if((b.c-E20[i])/A[i]>=dist&&b.c<b.o&&(b.h-b.c)/rg>=cp)return'SELL'})}
// SESSIONREV: build Asia 00-05 range, only trade 06-11 after excursion and close back inside.
for(let pad of [.1,.25,.4])for(let cp of [.55,.7])for(let rr of [1,1.25,1.5])for(let hold of [8,12]){let cfg={pad,cp,rr,sl:.9,hold};add('SESSIONREV',cfg,i=>{let h=hour(i);if(h<6||h>11)return;let day=new Date(M[i].t).toISOString().slice(0,10),H=-Infinity,L=Infinity;for(let j=i-1;j>=0;j--){if(new Date(M[j].t).toISOString().slice(0,10)!==day)break;let x=hour(j);if(x>=0&&x<6){H=Math.max(H,M[j].h);L=Math.min(L,M[j].l)}}if(!Number.isFinite(H))return;let b=M[i],rg=b.h-b.l;if(!(rg>0))return;if(b.h>H+pad*A[i]&&b.c<H&&b.c<b.o&&(b.h-b.c)/rg>=cp)return'SELL';if(b.l<L-pad*A[i]&&b.c>L&&b.c>b.o&&(b.c-b.l)/rg>=cp)return'BUY'})}
// DISLOC: M5 price stretched from EMA50 while short EMA20 slope disagrees with latest impulse; mean-reversion after confirming candle.
for(let dist of [1.5,2,2.5])for(let slope of [.05,.12,.2])for(let body of [.45,.6])for(let rr of [1,1.25,1.5]){let cfg={dist,slope,body,rr,sl:1,hold:12};add('DISLOC',cfg,i=>{if(i<12)return;let b=M[i],rg=b.h-b.l;if(!(rg>0)||Math.abs(b.c-b.o)/rg<body)return;let slp=(E20[i]-E20[i-6])/A[i];if((E50[i]-b.c)/A[i]>=dist&&slp>=-slope&&b.c>b.o)return'BUY';if((b.c-E50[i])/A[i]>=dist&&slp<=slope&&b.c<b.o)return'SELL'})}
X.sort((a,b)=>b.score-a.score);console.log(`REGIME / SESSION / DISLOCATION LAB | M5=${N} DEV=${C} HOLD=${N-C}`);for(let f of ['REGREV','SESSIONREV','DISLOC']){console.log(`\n🏆 ${f} TOP DEV + UNTOUCHED HOLD`);X.filter(x=>x.f===f).slice(0,15).forEach((x,k)=>{let h=st(run(x.fn,x.cfg,C,N));console.log(`${k+1} ${JSON.stringify(x.cfg)} | DEV T${x.d.n} WR${x.d.wr.toFixed(1)} PF${x.d.pf.toFixed(2)} N${x.d.net>=0?'+':''}${x.d.net.toFixed(2)} DD${x.d.dd.toFixed(2)} LS${x.d.ls} | HOLD T${h.n} WR${h.wr.toFixed(1)} PF${h.pf.toFixed(2)} N${h.net>=0?'+':''}${h.net.toFixed(2)} DD${h.dd.toFixed(2)} LS${h.ls}`)})}console.log('\nPROMOTION GATE: positive DEV + positive untouched HOLD, useful sample, stable PF/DD. Then blocks/months/cost and exact collision against current 8.');